--- 686/nes_native_sink165.c
+++ 687/nes_native_sink165.c
@@ -142,17 +142,21 @@
  /* A planner offer owns only three completed rows. Carry its exact full
   * extent into final output; never fetch the following rows early. The
   * window's last head proves no intervening tile/ordinary packet exists. */
- bool pair=early!=1 && s->map_pair683 && s->plan && s->plan->bank_history==2 &&
+ bool pairable=early!=1 && s->plan && s->plan->bank_history==2 &&
      s->plan->window && s->plan->window->last[0]==2 && s->plan->window->last[1]==2;
+ bool pair=pairable && s->map_pair683;
  s->map_pair683=false;
  for(unsigned g=s->map_next&127;g<64;){
-  if(!((mask>>g)&1)){g++;continue;}
+  if(!((mask>>g)&1)){g++;pair=false;continue;}
   unsigned first=g++,count=1;while(g<64&&count<3&&((mask>>g)&1)){g++;count++;}
-  bool adjacent=pair && first==(s->map_next&127) && count==3;
+  bool adjacent=pair && count==3;
   /* BG complete is a single adjacent packet, never a map drain. */
   if(early==2 && !adjacent)return true;
   if(!packet(s,(early==1||adjacent)?24:2,2,first*64,p->map+first*64,count*64))return false;
-  pair=false;
+  /* At most two exact192B map packets per producer query. Every
+   * packet retains checked queue credit/CRC/STOP; gaps and short tails query.
+   * BG-complete/row callbacks still return after their original one packet. */
+  pair=pairable && !adjacent && count==3;
   if(early){s->map_next=(uint8_t)g;s->map_pair683=early==1 && count==3;break;}
  }
  return true;
